import { Image } from 'expo-image';
import React from 'react';
import { View } from 'react-native';
import { FigmaIcon, type FigmaIconName } from './FigmaIcon';

/**
 * The nine marks on the Sections root, node 2031:5675.
 *
 * These used to be hand-drawn approximations — a rounded rect and two curves
 * standing in for a mark nobody had read. They are now the file's own
 * outlines, generated by `scripts/figma/extract-icons.js`; each keeps its own
 * aspect ratio, because the design's marks are not square (the ملكة mark is
 * 20 x 44 and the ﷺ calligraphy 34.1 x 29.5).
 *
 * `({ size })` is unchanged, so nothing downstream had to move.
 */
type Props = { size?: number };

/**
 * No default size. The design does not draw these at one size — inside the
 * same 64pt disc it sets الكتب العلمية at 48, القرآن at 44, أنتِ ملكة at
 * 20 x 44 and برامج إذاعية at 23 x 36 — so a caller that passes nothing gets
 * the size the file states. Forcing them all to one number was what made the
 * books mark 30% small and squashed the ملكة mark to 15 x 34.
 */
const fromFile = (name: FigmaIconName) =>
  function SectionIconFromFile({ size }: Props) {
    return <FigmaIcon name={name} size={size} />;
  };

export const QuranSectionIcon = fromFile('SectionQuran');
export const ProphetSectionIcon = fromFile('SectionProphet');
export const ScholarSectionIcon = fromFile('SectionScholars');
export const BookSectionIcon = fromFile('SectionBooks');
export const CrownSectionIcon = fromFile('SectionQueen');
export const HeadphonesSectionIcon = fromFile('SectionAudiobooks');
export const MicSectionIcon = fromFile('SectionRadio');
export const DesignSectionIcon = fromFile('SectionDawah');

/**
 * حصريات خزائن الرحمن — the one card whose mark the file does not state
 * entirely as vector.
 *
 * `Frame 5` (2355:1478) is 46 x 47: a gold disc with four small sparkles at
 * its lower left, and the words خزائن الرحمن set over them as a raster IMAGE
 * paint filling 42 x 47 from the frame's origin. The geometry walk reaches the
 * disc and the sparkles — in their true relative positions, so they are one
 * icon and not three overlaid guesses — and skips the raster, which comes out
 * of the archive's `images/` at its source 139 x 164 with alpha intact rather
 * than being redrawn or recovered from a flattened export.
 */
export function SparkleSectionIcon({ size = 47 }: Props) {
  const scale = size / 47; // the frame's longer edge, which `size` sets
  return (
    <View style={{ width: 46 * scale, height: 47 * scale }}>
      <FigmaIcon name="SectionExclusive" size={size} />
      <Image
        source={require('@/assets/figma/seal-khazain.png')}
        // `حصرى` is 42 x 47 at the frame's origin — flush left, full height.
        style={{ position: 'absolute', left: 0, top: 0, width: 42 * scale, height: 47 * scale }}
        contentFit="contain"
        // A bundled asset, so this never needs a round trip after first paint.
        cachePolicy="memory-disk"
      />
    </View>
  );
}

export const SECTION_ICONS = {
  quran: QuranSectionIcon,
  prophet: ProphetSectionIcon,
  scholar: ScholarSectionIcon,
  book: BookSectionIcon,
  crown: CrownSectionIcon,
  headphones: HeadphonesSectionIcon,
  sparkle: SparkleSectionIcon,
  mic: MicSectionIcon,
  design: DesignSectionIcon,
} as const;

export type SectionIconKey = keyof typeof SECTION_ICONS;
